<?php
namespace App\Controller\Admin;
use App\Entity\HelloAssoPayment;use App\Enum\HelloAssoPaymentMatchStatusEnum;use App\Repository\HelloAssoPaymentRepository;use App\Service\HelloAsso\HelloAssoPaymentProcessor;use Knp\Component\Pager\PaginatorInterface;use Symfony\Bundle\FrameworkBundle\Controller\AbstractController;use Symfony\Component\HttpFoundation\Request;use Symfony\Component\HttpFoundation\Response;use Symfony\Component\Routing\Attribute\Route;use Symfony\Component\Security\Http\Attribute\IsGranted;use Symfony\Contracts\Translation\TranslatorInterface;
#[IsGranted('ROLE_ADMIN')]
final class HelloAssoPaymentAdminController extends AbstractController{#[Route('/admin/lan/helloasso-payments',name:'app_admin_lan_helloasso_payment_index',methods:['GET'])]public function index(Request $request,HelloAssoPaymentRepository $repo,PaginatorInterface $paginator):Response{$status=HelloAssoPaymentMatchStatusEnum::tryFrom((string)$request->query->get('matchStatus',''));$pagination=$paginator->paginate($repo->createAdminListQueryBuilder(trim((string)$request->query->get('q',''))?:null,trim((string)$request->query->get('paymentState',''))?:null,$status,trim((string)$request->query->get('association',''))?:null),max(1,$request->query->getInt('page',1)),20);return $this->render('admin/lan/helloasso_payment/index.html.twig',['pagination'=>$pagination,'statuses'=>HelloAssoPaymentMatchStatusEnum::cases(),'filters'=>$request->query->all()]);}#[Route('/admin/lan/helloasso-payments/{id}',name:'app_admin_lan_helloasso_payment_show',requirements:['id'=>'\\d+'],methods:['GET'])]public function show(HelloAssoPayment $payment):Response{return $this->render('admin/lan/helloasso_payment/show.html.twig',['payment'=>$payment]);}#[Route('/admin/lan/helloasso-payments/{id}/reconcile',name:'app_admin_lan_helloasso_payment_reconcile',requirements:['id'=>'\\d+'],methods:['POST'])]public function reconcile(HelloAssoPayment $payment,Request $request,HelloAssoPaymentProcessor $processor,TranslatorInterface $translator):Response{if(!$this->isCsrfTokenValid('reconcile_helloasso_payment_'.$payment->getId(),(string)$request->request->get('_token'))){throw $this->createAccessDeniedException();}$processor->reconcile($payment);$this->addFlash('success',$translator->trans('helloasso_admin.flash.reconciled'));return $this->redirectToRoute('app_admin_lan_helloasso_payment_show',['id'=>$payment->getId()]);}}
